int hy[] = {2, 1, -1, -2, -2, -1, 1, 2};

int n;
int A[MAXN][MAXN];
pii dist[MAXM][MAXM];
pii dp[MAXN * MAXN][3];
pii pos[MAXN * MAXN];

pii operator+(const pii& a, const pii& b) {
