                    dist[getIndex(x, y, 1)][getIndex(w, y, 1)] = {1, 0};
                }
                if (w != y) {
                    dist[getIndex(x, y, 1)][getIndex(x, w, 1)] = {1, 0};
                }
            }

            for (int g = -n + 1; g < n; ++g) {
                if (g == 0) continue;

                if (isInside(x + g, y + g)) {
                    dist[getIndex(x, y, 2)][getIndex(x + g, y + g, 2)] = {1, 0};
                }
                if (isInside(x + g, y - g)) {
                    dist[getIndex(x, y, 2)][getIndex(x + g, y - g, 2)] = {1, 0};
                }
            }

            for (int b1 = 0; b1 < 3; ++b1) {
                for (int b2 = 0; b2 < 3; ++b2) {
                    if (b1 != b2) {
                        dist[getIndex(x, y, b1)][getIndex(x, y, b2)] = {1, 1};
                    }
                }
            }
        }
